{"proname":"community_award_recipients_lock","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.community_award_recipients_lock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' THEN PERFORM 1 FROM community_awards WHERE id = OLD.award_id FOR UPDATE; END IF;
  IF TG_OP <> 'DELETE' THEN PERFORM 1 FROM community_awards WHERE id = NEW.award_id FOR UPDATE; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$
"}

{"proname":"community_awards_check_recipient_trigger","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.community_awards_check_recipient_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'community_awards' THEN
