{"proname":"community_awards_check_recipients","arguments":"target uuid","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.community_awards_check_recipients(target uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE a community_awards; n integer;
BEGIN
  SELECT * INTO a FROM community_awards WHERE id = target;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(*) INTO n FROM community_award_recipients WHERE award_id = target;
  IF (a.status = 'awarded' AND (n < 1 OR NOT EXISTS (SELECT 1 FROM community_award_recipients WHERE award_id = target AND user_id = a.recipient_user_id)))
    OR (a.status <> 'awarded' AND n <> 0)
    OR (a.recipient_policy <> 'all_ties' AND n > a.recipient_limit) THEN
    RAISE EXCEPTION 'Community award outcome and recipient relation disagree' USING ERRCODE = '23514';
  END IF;
END $function$
"}

{"proname":"community_awards_legacy_guard","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.community_awards_legacy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_setting('rivalhub.community_awards_writer', true) IS DISTINCT FROM 'recipients-v1' THEN
    IF NEW.status IN ('awarded', 'not_awarded', 'cancelled') THEN
      IF NEW.recipient_policy <> 'single' OR (SELECT count(*) FROM community_award_recipients WHERE award_id = NEW.id) > 1 THEN
        RAISE EXCEPTION 'Use the current community award result writer for multiple recipients' USING ERRCODE = '23514';
      END IF;
      IF NEW.status <> 'cancelled' AND (NEW.settlement_policy <> 'season_complete' OR NOT EXISTS (
        SELECT 1 FROM seasons s WHERE s.id = NEW.season_id AND
        CASE WHEN s.competition_template = 'major' THEN EXISTS (SELECT 1 FROM major_final_results f WHERE f.season_id = s.id AND f.status = 'confirmed')
        ELSE s.status IN ('finished', 'archived') END
      )) THEN
        RAISE EXCEPTION 'Community award settlement is not ready for a legacy writer' USING ERRCODE = '23514';
      END IF;
    END IF;
    IF TG_OP = 'UPDATE' THEN NEW.result_version := OLD.result_version + 1; END IF;
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"community_awards_legacy_sync","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.community_awards_legacy_sync()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_setting('rivalhub.community_awards_writer', true) IS DISTINCT FROM 'recipients-v1' THEN
    DELETE FROM community_award_recipients WHERE award_id = NEW.id;
    IF NEW.status = 'awarded' THEN
      INSERT INTO community_award_recipients (award_id, user_id, position) VALUES (NEW.id, NEW.recipient_user_id, 0);
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.status IN ('awarded', 'not_awarded', 'cancelled') THEN
      INSERT INTO audit_logs (season_id, action, actor_id, target_id, target_type, meta)
      VALUES (NEW.season_id, 'community_award.legacy.resolve', NEW.outcome_by_user_id::text, NEW.id::text, 'community_award', jsonb_build_object(
        'previousStatus', OLD.status, 'status', NEW.status,
        'previousRecipientUserIds', CASE WHEN OLD.recipient_user_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(OLD.recipient_user_id) END,
        'recipientUserIds', CASE WHEN NEW.recipient_user_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(NEW.recipient_user_id) END,
        'previousOutcomeNote', OLD.outcome_note, 'outcomeNote', NEW.outcome_note));
    END IF;
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"dispatch_rivalhub_scheduler_job","arguments":"job_key text, publish_veto_closure boolean","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.dispatch_rivalhub_scheduler_job(job_key text, publish_veto_closure boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  p_job_key text := $1;
  checked_at timestamptz := clock_timestamp();
BEGIN
  IF p_job_key NOT IN (
    'draft-timeout',
    'check-registration-deadline',
    'match-time-auto-award',
    'cleanup-education-evidence',
    'refresh-steam-profiles',
    'resolve-match-veto-timeouts',
    'reconcile-predictions',
    'settle-match-mvp',
    'rebuild-statistics-projections'
  ) THEN
    RAISE EXCEPTION 'unknown scheduler job key' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.scheduled_job_health (job_key, last_primary_triggered_at, updated_at)
  VALUES (p_job_key, checked_at, checked_at)
  ON CONFLICT ON CONSTRAINT scheduled_job_health_pkey DO UPDATE SET
    last_primary_triggered_at = EXCLUDED.last_primary_triggered_at,
    updated_at = EXCLUDED.updated_at;

  IF NOT public.scheduler_job_is_due(p_job_key, publish_veto_closure) THEN
    RETURN NULL::bigint;
  END IF;

  RETURN public.enqueue_rivalhub_scheduler_job(p_job_key);
END;
$function$
"}

{"proname":"enforce_post_match_scope","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.enforce_post_match_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE match_season_id uuid; match_status text;
BEGIN
  IF TG_TABLE_NAME = 'match_commentators' AND TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM post_match_reports WHERE match_id = OLD.match_id) THEN RAISE EXCEPTION 'submitted commentator roster is immutable' USING ERRCODE = '23514'; END IF;
    RETURN OLD;
  END IF;
  SELECT season_id, status INTO match_season_id, match_status FROM matches WHERE id = NEW.match_id;
  IF match_season_id IS NULL THEN RAISE EXCEPTION 'match does not exist' USING ERRCODE = '23503'; END IF;
  IF TG_TABLE_NAME = 'match_commentators' THEN
    IF match_status = 'cancelled' THEN RAISE EXCEPTION 'cancelled match cannot have commentators' USING ERRCODE = '23514'; END IF;
    IF EXISTS (SELECT 1 FROM post_match_reports WHERE match_id = NEW.match_id) THEN RAISE EXCEPTION 'submitted commentator roster is immutable' USING ERRCODE = '23514'; END IF;
    IF NOT EXISTS (SELECT 1 FROM season_admin_grants WHERE season_id = match_season_id AND user_id = NEW.user_id)
       AND NOT EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id AND role = 'super_admin') THEN RAISE EXCEPTION 'commentator must be a season admin' USING ERRCODE = '23514'; END IF;
    IF (SELECT count(*) FROM match_commentators WHERE match_id = NEW.match_id) >= 2 THEN RAISE EXCEPTION 'a match has at most two commentators' USING ERRCODE = '23514'; END IF;
  ELSE
    IF match_status <> 'finished' THEN RAISE EXCEPTION 'post-match reports require a finished match' USING ERRCODE = '23514'; END IF;
    -- A non-commentator can only create an explicitly reopened correction as a real platform super-admin.
    -- UPDATE must not replace an existing confirmation's submitter with an administrator.
    IF NOT EXISTS (SELECT 1 FROM match_commentators WHERE match_id = NEW.match_id AND user_id = NEW.submitted_by_user_id)
       AND NOT (
         TG_OP = 'INSERT'
         AND EXISTS (SELECT 1 FROM users WHERE id = NEW.submitted_by_user_id AND role = 'super_admin')
         AND EXISTS (SELECT 1 FROM match_commentators WHERE match_id = NEW.match_id)
         AND EXISTS (SELECT 1 FROM audit_logs WHERE target_id = NEW.match_id::text AND action = 'postmatch.report.revoke')
         AND NOT EXISTS (SELECT 1 FROM post_match_reports WHERE match_id = NEW.match_id)
       ) THEN RAISE EXCEPTION 'confirmation requires a registered commentator or a super-admin correcting a reopened nonempty roster' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"enqueue_match_veto_invalidation","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.enqueue_match_veto_invalidation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE data jsonb := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  mid uuid; category jsonb; current_tx bigint := txid_current();
BEGIN
  IF TG_TABLE_NAME='match_veto_appeals' THEN
    SELECT match_id INTO mid FROM match_veto_timeout_incidents WHERE id=(data->>'timeout_incident_id')::uuid;
  ELSIF TG_TABLE_NAME='match_roster_players' THEN
    SELECT match_id INTO mid FROM match_rosters WHERE id=(data->>'roster_id')::uuid;
  ELSE
    mid := (data->>'match_id')::uuid;
  END IF;
  -- Parent deletion already cascades the watermark; never recreate an orphan.
  IF mid IS NULL OR NOT EXISTS (SELECT 1 FROM matches WHERE id=mid AND season_id IS NOT NULL) THEN
    RETURN COALESCE(NEW,OLD);
  END IF;
  category := CASE WHEN TG_TABLE_NAME='match_maps' THEN '["map_plan"]'::jsonb WHEN TG_TABLE_NAME='match_veto_appeals' THEN '["appeals"]'::jsonb
    WHEN TG_TABLE_NAME IN ('match_rosters','match_roster_players') THEN '["lineups"]'::jsonb ELSE '["veto_step"]'::jsonb END;
  INSERT INTO match_veto_invalidations(match_id,generation,published_generation,affected_facts,last_transaction_id)
    VALUES(mid,1,0,category,current_tx)
    ON CONFLICT(match_id) DO UPDATE SET
      generation=match_veto_invalidations.generation + CASE WHEN match_veto_invalidations.last_transaction_id=current_tx THEN 0 ELSE 1 END,
      affected_facts=CASE WHEN match_veto_invalidations.published_generation=match_veto_invalidations.generation THEN category
        ELSE (SELECT jsonb_agg(DISTINCT fact) FROM jsonb_array_elements(match_veto_invalidations.affected_facts || category) fact) END,
      last_transaction_id=current_tx,updated_at=clock_timestamp()
    WHERE match_veto_invalidations.last_transaction_id<>current_tx OR NOT match_veto_invalidations.affected_facts @> category;
  RETURN COALESCE(NEW,OLD);
END $function$
"}

{"proname":"enqueue_rivalhub_scheduler_job","arguments":"job_key text","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.enqueue_rivalhub_scheduler_job(job_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  p_job_key text := $1;
  base_url text;
  cron_secret text;
  requested_at timestamptz := clock_timestamp();
  request_id bigint;
BEGIN
  IF p_job_key NOT IN (
    'draft-timeout',
    'check-registration-deadline',
    'match-time-auto-award',
    'cleanup-education-evidence',
    'refresh-steam-profiles',
    'resolve-match-veto-timeouts',
    'reconcile-predictions',
    'settle-match-mvp',
    'rebuild-statistics-projections'
  ) THEN
    RAISE EXCEPTION 'unknown scheduler job key' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.scheduled_job_health (job_key, last_primary_dispatch_requested_at, updated_at)
  VALUES (p_job_key, requested_at, requested_at)
  ON CONFLICT ON CONSTRAINT scheduled_job_health_pkey DO UPDATE SET
    last_primary_dispatch_requested_at = EXCLUDED.last_primary_dispatch_requested_at,
    updated_at = EXCLUDED.updated_at;

  IF to_regnamespace('vault') IS NULL THEN
    RAISE EXCEPTION 'scheduler vault is unavailable' USING ERRCODE = '0A000';
  END IF;
  EXECUTE 'SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = $1'
    INTO base_url USING 'rivalhub_scheduler_base_url';
  EXECUTE 'SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = $1'
    INTO cron_secret USING 'rivalhub_cron_secret';
  IF NULLIF(trim(base_url), '') IS NULL OR NULLIF(cron_secret, '') IS NULL THEN
    RAISE EXCEPTION 'scheduler credentials are unavailable' USING ERRCODE = '22023';
  END IF;

  IF to_regnamespace('net') IS NULL THEN
    RAISE EXCEPTION 'scheduler HTTP extension is unavailable' USING ERRCODE = '0A000';
  END IF;
  base_url := regexp_replace(trim(base_url), '/+$', '');
  EXECUTE 'SELECT net.http_get($1, $2::jsonb, $3::jsonb, $4)'
    INTO request_id
    USING
      base_url || '/api/cron/' || p_job_key,
      '{}'::jsonb,
      jsonb_build_object(
        'Authorization', 'Bearer ' || cron_secret,
        'X-RivalHub-Cron-Source', 'supabase-primary'
      ),
      10000;
  RETURN request_id;
END;
$function$
"}

{"proname":"rivalhub_assert_competition_entry_aggregate","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_assert_competition_entry_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE valid boolean;
BEGIN
  IF TG_TABLE_NAME = 'competition_entry_roster_members' THEN
    SELECT EXISTS (
      SELECT 1 FROM competition_entry_roster_revisions revision
      JOIN competition_entry_participants participant ON participant.id = NEW.participant_id
      WHERE revision.id = NEW.revision_id AND revision.entry_id = participant.entry_id
        AND participant.user_id = NEW.user_id
    ) INTO valid;
  ELSIF TG_TABLE_NAME = 'competition_entry_active_claims' THEN
    SELECT EXISTS (
      SELECT 1 FROM competition_entries entry
      JOIN competition_entry_participants participant ON participant.id = NEW.participant_id
      WHERE entry.id = NEW.entry_id AND entry.competition_id = NEW.competition_id
        AND participant.entry_id = NEW.entry_id AND participant.user_id = NEW.user_id
    ) INTO valid;
  ELSIF TG_TABLE_NAME = 'event_rosters' THEN
    SELECT NEW.source_roster_revision_id IS NULL OR EXISTS (
      SELECT 1 FROM competition_entry_roster_revisions revision
      WHERE revision.id = NEW.source_roster_revision_id AND revision.entry_id = NEW.entry_id
    ) INTO valid;
  ELSIF TG_TABLE_NAME = 'event_roster_members' THEN
    SELECT NEW.participant_id IS NULL OR EXISTS (
      SELECT 1 FROM event_rosters roster
      JOIN competition_entry_participants participant ON participant.id = NEW.participant_id
      WHERE roster.id = NEW.event_roster_id AND roster.entry_id = participant.entry_id
        AND participant.user_id = NEW.user_id
    ) INTO valid;
  ELSIF TG_TABLE_NAME = 'match_rosters' THEN
    SELECT EXISTS (
      SELECT 1 FROM matches match
      WHERE match.id = NEW.match_id AND NEW.entry_id IN (match.entry_a_id, match.entry_b_id)
    ) INTO valid;
  ELSIF TG_TABLE_NAME = 'match_roster_players' THEN
    SELECT EXISTS (
      SELECT 1 FROM match_rosters match_roster
      JOIN event_roster_members member ON member.id = NEW.event_roster_member_id
      JOIN event_rosters event_roster ON event_roster.id = member.event_roster_id
      WHERE match_roster.id = NEW.roster_id
        AND match_roster.entry_id = event_roster.entry_id
    ) INTO valid;
  END IF;
  IF NOT COALESCE(valid, false) THEN
    RAISE EXCEPTION 'CompetitionEntry cross-aggregate invariant violated for %', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"rivalhub_assert_competition_entry_current_state","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_assert_competition_entry_current_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  affected_entry_id uuid;
  entry_row record;
  current_revision record;
  approved_revision record;
  latest_representative record;
  previous_representative record;
BEGIN
  IF TG_TABLE_NAME = 'competition_entries' THEN
    affected_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  ELSIF TG_TABLE_NAME IN ('competition_entry_roster_revisions', 'competition_entry_representative_changes') THEN
    affected_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_id ELSE NEW.entry_id END;
  END IF;

  SELECT * INTO entry_row FROM competition_entries WHERE id = affected_entry_id;
  IF NOT FOUND THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT * INTO current_revision
  FROM competition_entry_roster_revisions
  WHERE id = entry_row.current_roster_revision_id
    AND entry_id = affected_entry_id;
  IF current_revision IS NULL OR current_revision.revision_number <> (
    SELECT max(revision_number) FROM competition_entry_roster_revisions WHERE entry_id = affected_entry_id
  ) THEN
    RAISE EXCEPTION 'CompetitionEntry current roster pointer must target its latest revision' USING ERRCODE = '23514';
  END IF;

  IF entry_row.approved_roster_revision_id IS NOT NULL THEN
    SELECT * INTO approved_revision
    FROM competition_entry_roster_revisions
    WHERE id = entry_row.approved_roster_revision_id
      AND entry_id = affected_entry_id;
    IF approved_revision IS NULL OR approved_revision.status <> 'approved' THEN
      RAISE EXCEPTION 'CompetitionEntry approved roster pointer must target an approved revision in the same Entry' USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT * INTO latest_representative
  FROM competition_entry_representative_changes
  WHERE entry_id = affected_entry_id
  ORDER BY changed_at DESC, id DESC
  LIMIT 1;
  IF latest_representative IS NULL OR latest_representative.to_user_id <> entry_row.representative_user_id THEN
    RAISE EXCEPTION 'CompetitionEntry representative pointer must match the latest representative change' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' AND TG_TABLE_NAME = 'competition_entry_representative_changes' THEN
    SELECT * INTO previous_representative
    FROM competition_entry_representative_changes
    WHERE entry_id = NEW.entry_id
      AND (changed_at, id) < (NEW.changed_at, NEW.id)
    ORDER BY changed_at DESC, id DESC
    LIMIT 1;
    IF (previous_representative IS NULL AND NEW.from_user_id IS NOT NULL)
      OR (previous_representative IS NOT NULL AND NEW.from_user_id IS DISTINCT FROM previous_representative.to_user_id) THEN
      RAISE EXCEPTION 'Representative change from_user_id must continue the append-only chain' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
"}

{"proname":"rivalhub_assert_event_roster_approved_source","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_assert_event_roster_approved_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  affected_entry_id uuid;
  roster record;
BEGIN
  IF TG_TABLE_NAME = 'event_rosters' THEN
    affected_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_id ELSE NEW.entry_id END;
  ELSIF TG_TABLE_NAME = 'competition_entries' THEN
    affected_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  ELSE
    affected_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_id ELSE NEW.entry_id END;
  END IF;

  FOR roster IN SELECT * FROM event_rosters WHERE entry_id = affected_entry_id LOOP
    IF roster.status IN ('confirmed', 'frozen') THEN
      IF roster.source_roster_revision_id IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM competition_entries entry
          WHERE entry.id = affected_entry_id
            AND entry.approved_roster_revision_id = roster.source_roster_revision_id
        )
        OR NOT EXISTS (
          SELECT 1 FROM competition_entry_roster_revisions revision
          WHERE revision.id = roster.source_roster_revision_id
            AND revision.entry_id = affected_entry_id
            AND revision.status = 'approved'
        ) THEN
        RAISE EXCEPTION 'Confirmed or frozen EventRoster must source the approved Entry roster revision' USING ERRCODE = '23514';
      END IF;
    END IF;
  END LOOP;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
"}

{"proname":"rivalhub_assert_event_roster_mutable","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_assert_event_roster_mutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE roster_id uuid;
BEGIN
  IF current_setting('rivalhub.identity_merge_reparent', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  roster_id := COALESCE(NEW.event_roster_id, OLD.event_roster_id);
  IF EXISTS (SELECT 1 FROM event_rosters WHERE id = roster_id AND status = 'frozen') THEN
    RAISE EXCEPTION 'frozen event roster members are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$
"}

{"proname":"rivalhub_assert_team_current_state","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_assert_team_current_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  affected_team_id uuid;
  team_row record;
  latest_captain record;
  latest_name record;
  previous_captain record;
  previous_name record;
BEGIN
  IF TG_TABLE_NAME = 'teams' THEN
    affected_team_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  ELSIF TG_TABLE_NAME IN ('team_memberships', 'team_captain_changes', 'team_name_changes') THEN
    affected_team_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.team_id ELSE NEW.team_id END;
  END IF;

  SELECT * INTO team_row FROM teams WHERE id = affected_team_id;
  IF NOT FOUND THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT * INTO latest_captain
  FROM team_captain_changes
  WHERE team_id = affected_team_id
  ORDER BY changed_at DESC, id DESC
  LIMIT 1;
  IF latest_captain IS NULL OR latest_captain.to_user_id <> team_row.captain_user_id THEN
    RAISE EXCEPTION 'Team captain pointer must match the latest captain change' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO latest_name
  FROM team_name_changes
  WHERE team_id = affected_team_id
  ORDER BY changed_at DESC, id DESC
  LIMIT 1;
  IF latest_name IS NULL OR latest_name.new_name <> team_row.name THEN
    RAISE EXCEPTION 'Team name must match the latest name change' USING ERRCODE = '23514';
  END IF;

  IF team_row.status = 'active' AND NOT EXISTS (
    SELECT 1 FROM team_memberships membership
    WHERE membership.team_id = affected_team_id
      AND membership.user_id = team_row.captain_user_id
      AND membership.status = 'active'
      AND membership.ended_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Active Team captain must have an active current membership' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' AND TG_TABLE_NAME = 'team_captain_changes' THEN
    SELECT * INTO previous_captain
    FROM team_captain_changes
    WHERE team_id = NEW.team_id
      AND (changed_at, id) < (NEW.changed_at, NEW.id)
    ORDER BY changed_at DESC, id DESC
    LIMIT 1;
    IF (previous_captain IS NULL AND NEW.from_user_id IS NOT NULL)
      OR (previous_captain IS NOT NULL AND NEW.from_user_id IS DISTINCT FROM previous_captain.to_user_id) THEN
      RAISE EXCEPTION 'Captain change from_user_id must continue the append-only chain' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_OP = 'INSERT' AND TG_TABLE_NAME = 'team_name_changes' THEN
    SELECT * INTO previous_name
    FROM team_name_changes
    WHERE team_id = NEW.team_id
      AND (changed_at, id) < (NEW.changed_at, NEW.id)
    ORDER BY changed_at DESC, id DESC
    LIMIT 1;
    IF (previous_name IS NULL AND NEW.old_name IS NOT NULL)
      OR (previous_name IS NOT NULL AND NEW.old_name IS DISTINCT FROM previous_name.new_name) THEN
      RAISE EXCEPTION 'Name change old_name must continue the append-only chain' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
"}

{"proname":"rivalhub_bet_official_outbox","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_bet_official_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE rowdata jsonb := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  sid uuid; mid uuid; matchrow public.matches;
BEGIN
  IF TG_TABLE_NAME IN ('matches','major_stage_runs','major_prestart_states','major_tournament_entrants','major_tournament_seeds','major_final_results','match_demo_imports') THEN
    sid := (rowdata->>'season_id')::uuid;
    IF TG_TABLE_NAME='matches' THEN mid := (rowdata->>'id')::uuid; END IF;
  ELSIF TG_TABLE_NAME IN ('match_maps','match_veto_sessions','match_player_stats','match_veto_timeout_incidents') THEN
    mid := (rowdata->>'match_id')::uuid;
    SELECT * INTO matchrow FROM matches WHERE id=mid; sid := matchrow.season_id;
  ELSIF TG_TABLE_NAME='match_veto_appeals' THEN
    SELECT m.* INTO matchrow FROM matches m JOIN match_veto_timeout_incidents i ON i.match_id=m.id WHERE i.id=(rowdata->>'timeout_incident_id')::uuid;
    sid:=matchrow.season_id; mid:=matchrow.id;
  ELSIF TG_TABLE_NAME='event_rosters' THEN
    SELECT competition_id INTO sid FROM competition_entries WHERE id=(rowdata->>'entry_id')::uuid;
  ELSIF TG_TABLE_NAME='event_roster_members' THEN
    SELECT e.competition_id INTO sid FROM event_rosters r JOIN competition_entries e ON e.id=r.entry_id WHERE r.id=(rowdata->>'event_roster_id')::uuid;
  END IF;
  IF sid IS NULL THEN RETURN COALESCE(NEW,OLD); END IF;
  -- Serialize before touching market rows, matching workers and administrative operations.
  -- Workers never lock official rows, so an official writer can safely wait here.
  PERFORM 1 FROM bet_programs WHERE season_id=sid FOR UPDATE;
  -- Lock financial admission in the official transaction, never wait for settlement.
  IF TG_TABLE_NAME='matches' THEN
    IF TG_OP='DELETE' OR rowdata->>'status' IN ('finished','cancelled') OR (rowdata->>'is_forfeit')::boolean
      OR (TG_OP='UPDATE' AND (NEW.entry_a_id IS DISTINCT FROM OLD.entry_a_id OR NEW.entry_b_id IS DISTINCT FROM OLD.entry_b_id OR NEW.format IS DISTINCT FROM OLD.format OR NEW.major_stage_run_id IS DISTINCT FROM OLD.major_stage_run_id OR NEW.qualification_run_id IS DISTINCT FROM OLD.qualification_run_id)) THEN
      UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND match_id=mid;
    ELSIF rowdata->>'gameplay_started_at' IS NOT NULL THEN
      UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND match_id=mid AND (subject->>'kind'='match' OR subject->>'mapOrder'='1');
    END IF;
  ELSIF TG_TABLE_NAME='match_veto_sessions' AND rowdata->>'started_at' IS NOT NULL THEN
    UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND match_id=mid AND type LIKE 'veto_%';
    IF matchrow.major_stage_run_id IS NOT NULL THEN
      UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND season_id=sid AND subject->>'kind'='event';
    END IF;
  ELSIF TG_TABLE_NAME='match_maps' AND (rowdata->>'started_at' IS NOT NULL OR rowdata->>'completed_at' IS NOT NULL) THEN
    -- A confirmed map start/result proves the series has begun, even when the
    -- operator did not separately record gameplay_started_at.
    UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND match_id=mid AND (subject->>'kind'='match' OR subject->>'mapId'=rowdata->>'id' OR (subject->>'kind'='map_slot' AND (subject->>'mapOrder')::integer <= (rowdata->>'map_order')::integer));
    IF matchrow.major_stage_run_id IS NOT NULL THEN
      UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND season_id=sid AND subject->>'kind'='event';
    END IF;
  END IF;
  -- Lock remaining map pools at confirmed clinch even before match.finished.
  -- Corrections may change winners/refunds, but never erase a financial lock.
  IF TG_TABLE_NAME='match_maps' AND EXISTS (
    SELECT 1 FROM match_maps mm WHERE mm.match_id=mid AND mm.completed_at IS NOT NULL
    GROUP BY mm.match_id HAVING
      count(*) FILTER (WHERE mm.score_a > mm.score_b) >= CASE matchrow.format WHEN 'bo1' THEN 1 WHEN 'bo3' THEN 2 ELSE 3 END
      OR count(*) FILTER (WHERE mm.score_b > mm.score_a) >= CASE matchrow.format WHEN 'bo1' THEN 1 WHEN 'bo3' THEN 2 ELSE 3 END
  ) THEN
    UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp())
      WHERE locked_at IS NULL AND match_id=mid AND subject->>'kind' IN ('map','map_slot');
  END IF;
  IF TG_TABLE_NAME='matches' AND rowdata->>'gameplay_started_at' IS NOT NULL AND rowdata->>'major_stage_run_id' IS NOT NULL THEN
    UPDATE bet_markets SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE locked_at IS NULL AND season_id=sid AND subject->>'kind'='event';
  END IF;
  UPDATE bet_programs SET dirty=true,updated_at=clock_timestamp() WHERE season_id=sid;
  IF TG_TABLE_NAME='major_stage_runs' AND TG_OP='INSERT' AND EXISTS(SELECT 1 FROM bet_programs WHERE season_id=sid) THEN
    INSERT INTO bet_stage_milestones(season_id,stage_key,opened_at) VALUES(sid,NEW.stage_key,NEW.started_at) ON CONFLICT DO NOTHING;
  END IF;
  RETURN COALESCE(NEW,OLD);
END $function$
"}

{"proname":"rivalhub_enqueue_predictions","arguments":"","prokind":"f","owner":"postgres","proacl":null,"definition":"CREATE OR REPLACE FUNCTION public.rivalhub_enqueue_predictions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE sid uuid;
BEGIN
  sid := COALESCE(NEW.season_id, OLD.season_id);
  IF NOT EXISTS (SELECT 1 FROM prediction_programs WHERE season_id = sid) THEN RETURN COALESCE(NEW,OLD); END IF;
  INSERT INTO prediction_jobs(season_id,dirty,updated_at) VALUES(sid,true,clock_timestamp()) ON CONFLICT(season_id) DO UPDATE SET dirty=true,updated_at=clock_timestamp();
  IF TG_TABLE_NAME = 'major_stage_runs' AND TG_OP = 'INSERT' THEN
    INSERT INTO prediction_stage_milestones(season_id,stage_key,opened_at)
    VALUES(NEW.season_id,NEW.stage_key,NEW.started_at) ON CONFLICT(season_id,stage_key) DO NOTHING;
  END IF;
  UPDATE prediction_contests SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE season_id=sid AND deadline <= clock_timestamp();
  IF TG_TABLE_NAME = 'matches' THEN
    IF TG_OP <> 'DELETE' AND NEW.status IN ('in_progress','finished') THEN
      UPDATE prediction_contests SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE season_id=sid AND stage_key=NEW.stage;
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'matches' THEN
    UPDATE prediction_contests c SET deadline=(
      SELECT min(m.scheduled_at) FROM matches m
      WHERE m.season_id=sid AND m.stage=c.stage_key AND m.ownership='major_stage' AND m.status <> 'cancelled'
    ) WHERE c.season_id=sid AND c.locked_at IS NULL;
    UPDATE prediction_contests SET locked_at=COALESCE(locked_at,clock_timestamp()) WHERE season_id=sid AND deadline <= clock_timestamp();
  END IF;
  RETURN COALESCE(NEW,OLD);
END $function$
"}

{"proname":"rivalhub_gameplay_start_is_permanent","arguments":"","prokind":"f","owner":"postgres","proacl":"{postgres=X/postgres}","definition":"CREATE OR REPLACE FUNCTION public.rivalhub_gameplay_start_is_permanent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_TABLE_NAME='matches' THEN
    IF OLD.gameplay_started_at IS NOT NULL AND NEW.gameplay_started_at IS DISTINCT FROM OLD.gameplay_started_at THEN RAISE EXCEPTION 'gameplay start is permanent' USING ERRCODE='23514'; END IF;
  ELSE
    IF OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at THEN RAISE EXCEPTION 'map start is permanent' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"rivalhub_guard_retired_prediction_ledger","arguments":"","prokind":"f","owner":"postgres","proacl":null,"definition":"CREATE OR REPLACE FUNCTION public.rivalhub_guard_retired_prediction_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' AND (OLD.kind IN ('stake', 'settlement') OR OLD.source LIKE 'stake/%' OR OLD.source LIKE 'settlement/%' OR OLD.source LIKE 'reversal/%' OR (OLD.kind = 'reversal' AND OLD.source NOT LIKE 'void/%')) THEN
    RAISE EXCEPTION 'legacy prediction finance is retired' USING ERRCODE = '23514';
  END IF;
  IF TG_OP <> 'DELETE' AND (NEW.kind IN ('stake', 'settlement') OR NEW.source LIKE 'stake/%' OR NEW.source LIKE 'settlement/%' OR NEW.source LIKE 'reversal/%' OR (NEW.kind = 'reversal' AND NEW.source NOT LIKE 'void/%')) THEN
    RAISE EXCEPTION 'legacy prediction finance is retired' USING ERRCODE = '23514';
  END IF;
  IF TG_OP <> 'DELETE' AND NEW.kind = 'reversal' AND NEW.source LIKE 'void/%' AND NOT EXISTS (
    SELECT 1 FROM public.prediction_ledger reward WHERE NEW.source = 'void/' || reward.id::text
      AND reward.kind = 'participation' AND reward.season_id = NEW.season_id AND reward.account_id = NEW.account_id
      AND NEW.amount = -reward.amount AND NEW.profit = -reward.profit
  ) THEN RAISE EXCEPTION 'invalid PickEm participation reversal' USING ERRCODE = '23514'; END IF;
  RETURN COALESCE(NEW, OLD);
END $function$
"}

{"proname":"rivalhub_prediction_frozen_config","arguments":"","prokind":"f","owner":"postgres","proacl":null,"definition":"CREATE OR REPLACE FUNCTION public.rivalhub_prediction_frozen_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'prediction_programs' THEN
    IF (to_jsonb(NEW) - 'paused') IS DISTINCT FROM (to_jsonb(OLD) - 'paused') THEN RAISE EXCEPTION 'prediction rules are frozen' USING ERRCODE='23514'; END IF;
  ELSIF TG_TABLE_NAME = 'prediction_markets' THEN
    IF (to_jsonb(NEW)-'locked_at'-'deadline') IS DISTINCT FROM (to_jsonb(OLD)-'locked_at'-'deadline') OR NEW.deadline > OLD.deadline OR (OLD.locked_at IS NOT NULL AND NEW.locked_at IS DISTINCT FROM OLD.locked_at) THEN RAISE EXCEPTION 'market identity and lock are frozen' USING ERRCODE='23514'; END IF;
  ELSE
    IF (to_jsonb(NEW)-'stage_run_id'-'locked_at'-'deadline'-'voided_at'-'void_reason') IS DISTINCT FROM (to_jsonb(OLD)-'stage_run_id'-'locked_at'-'deadline'-'voided_at'-'void_reason') OR (OLD.stage_run_id IS NOT NULL AND NEW.stage_run_id IS DISTINCT FROM OLD.stage_run_id) OR (OLD.locked_at IS NOT NULL AND NEW.deadline IS DISTINCT FROM OLD.deadline) OR (OLD.locked_at IS NOT NULL AND NEW.locked_at IS DISTINCT FROM OLD.locked_at) OR (OLD.voided_at IS NOT NULL AND NEW.voided_at IS DISTINCT FROM OLD.voided_at) THEN RAISE EXCEPTION 'contest identity and lock are frozen' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"rivalhub_test_match_identity","arguments":"","prokind":"f","owner":"postgres","proacl":null,"definition":"CREATE OR REPLACE FUNCTION public.rivalhub_test_match_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF (OLD.test_config IS NULL) IS DISTINCT FROM (NEW.test_config IS NULL) THEN
    RAISE EXCEPTION 'Match test purpose is immutable';
  END IF;
  IF OLD.test_config IS NOT NULL AND (
    OLD.season_id IS DISTINCT FROM NEW.season_id OR
    OLD.entry_a_id IS DISTINCT FROM NEW.entry_a_id OR
    OLD.entry_b_id IS DISTINCT FROM NEW.entry_b_id OR
    OLD.test_config->'mapPool' IS DISTINCT FROM NEW.test_config->'mapPool' OR
    OLD.test_config->'eligibility' IS DISTINCT FROM NEW.test_config->'eligibility'
  ) THEN
    RAISE EXCEPTION 'Test match affiliation, participants and map pool are frozen';
  END IF;
  RETURN NEW;
END $function$
"}

{"proname":"validate_major_final_result","arguments":"","prokind":"f","owner":"postgres","proacl":null,"definition":"CREATE OR REPLACE FUNCTION public.validate_major_final_result()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  group_value jsonb;
  entry_value jsonb;
  expected_from integer := 1;
  placement_count integer := 0;
  entrant_count integer := 0;
  first_entry uuid;
  entry_id uuid;
BEGIN
  SELECT count(*) INTO entrant_count
  FROM "public"."major_tournament_entrants"
  WHERE "season_id" = NEW.season_id;

  IF jsonb_typeof(NEW.placement_groups) <> 'array' THEN
    RAISE EXCEPTION 'major_final_results placement_groups must be an array';
  END IF;

  FOR group_value IN SELECT value FROM jsonb_array_elements(NEW.placement_groups) LOOP
    IF jsonb_typeof(group_value) <> 'object'
      OR NOT (group_value ? 'from' AND group_value ? 'to' AND group_value ? 'entryIds')
      OR jsonb_typeof(group_value->'entryIds') <> 'array' THEN
      RAISE EXCEPTION 'major_final_results placement group shape invalid';
    END IF;
    IF (group_value->>'from') !~ '^[0-9]+$' OR (group_value->>'to') !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'major_final_results placement range invalid';
    END IF;
    IF (group_value->>'from')::integer <> expected_from
      OR (group_value->>'to')::integer < expected_from
      OR jsonb_array_length(group_value->'entryIds') <> (group_value->>'to')::integer - expected_from + 1 THEN
      RAISE EXCEPTION 'major_final_results placement groups not contiguous';
    END IF;
    FOR entry_value IN SELECT value FROM jsonb_array_elements(group_value->'entryIds') LOOP
      BEGIN
        entry_id := trim(both '"' from entry_value::text)::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'major_final_results entry id invalid';
      END;
      IF placement_count = 0 THEN first_entry := entry_id; END IF;
      IF NOT EXISTS (
        SELECT 1 FROM "public"."competition_entries"
        WHERE id = entry_id AND competition_id = NEW.season_id
      ) THEN
        RAISE EXCEPTION 'major_final_results entry outside season';
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM "public"."major_tournament_entrants"
        WHERE season_id = NEW.season_id AND competition_entry_id = entry_id
      ) THEN
        RAISE EXCEPTION 'major_final_results entry outside materialized entrants';
      END IF;
      IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.placement_groups) g,
             jsonb_array_elements(g.value->'entryIds') e
        WHERE trim(both '"' from e.value::text)::uuid = entry_id
      ) AND placement_count > 0 THEN
        IF (
          SELECT count(*)
          FROM jsonb_array_elements(NEW.placement_groups) g,
               jsonb_array_elements(g.value->'entryIds') e
          WHERE trim(both '"' from e.value::text)::uuid = entry_id
        ) > 1 THEN
          RAISE EXCEPTION 'major_final_results duplicate entry';
        END IF;
      END IF;
      placement_count := placement_count + 1;
    END LOOP;
    expected_from := (group_value->>'to')::integer + 1;
  END LOOP;

  IF expected_from <> entrant_count + 1
    OR placement_count <> entrant_count
    OR first_entry IS DISTINCT FROM NEW.champion_entry_id THEN
    RAISE EXCEPTION 'major_final_results champion/placement mismatch';
  END IF;
  RETURN NEW;
END $function$
"}
